for root, dirs, files in os.walk('.'):
    for f in files:
        if f.endswith('.py'):
            path = os.path.join(root, f)
            with open(path, 'r', encoding='utf-8') as file:
                content = file.read()
                if 'legacy_auth' in content and 'app/auth.py' not in path:
                    files_to_check.append(path)

print(f"Found {len(files_to_check)} files to migrate.")

for path in sorted(files_to_check):
    print(f"\n--- {path} ---")
    with open(path, 'r', encoding='utf-8') as f:
        lines = f.readlines()
        for i, line in enumerate(lines):
            if 'legacy_auth' in line:
                # print a context window around the legacy_auth line
                start = max(0, i - 4)
                end = min(len(lines), i + 5)
                for idx in range(start, end):
                    marker = "-> " if idx == i else "   "
                    print(f"{marker}{idx+1}: {lines[idx].rstrip()}")

