import os
import re
import ast

def analyze_returns():
    files_to_check = []
    for root, dirs, files in os.walk('.'):
        for f in files:
            if f.endswith('.py'):
                path = os.path.join(root, f)
                if 'app/auth.py' in path or 'dry_run_migrate.py' in path:
                    continue
                with open(path, 'r', encoding='utf-8') as file:
                    content = file.read()
                    if 'legacy_auth' in content:
                        files_to_check.append(path)

    for path in sorted(files_to_check):
        with open(path, 'r', encoding='utf-8') as f:
            source = f.read()

        tree = ast.parse(source)
        lines = source.splitlines()

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                has_legacy_auth = False
                for subnode in ast.walk(node):
                    if isinstance(subnode, ast.Call) and isinstance(subnode.func, ast.Name) and subnode.func.id == 'legacy_auth':
                        has_legacy_auth = True
                        break

                if has_legacy_auth:
                    start_line = node.lineno - 1
                    end_line = getattr(node, 'end_lineno', len(lines))
                    func_source = "\n".join(lines[start_line:end_line])

                    # find all return statements inside this function using AST
                    return_statements = []
                    for subnode in ast.walk(node):
                        if isinstance(subnode, ast.Return):
                            # format the return node back to source line
                            r_start = subnode.lineno - 1
                            r_end = getattr(subnode, 'end_lineno', r_start + 1)
                            return_statements.append(" ".join(lines[r_start:r_end]).strip())

                    print(f"File: {path} | Function: {node.name}")
                    print(f"  Returns: {return_statements}")

analyze_returns()
